import argparse
import json
import os
import sys
import time
from datetime import datetime, timedelta
import requests

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('repo', help='Repository identifier in the form owner/repo')
    return parser.parse_args()

def get_cache_path():
    return os.path.expanduser('~/.repo_cache.dat')

def load_cache():
    cache = {}
    if os.path.exists(get_cache_path()):
        with open(get_cache_path(), 'r') as f:
            try:
                cache = json.load(f)
            except json.JSONDecodeError:
                pass
    return cache

def save_cache(cache):
    with open(get_cache_path(), 'w') as f:
        json.dump(cache, f)

def is_cache_valid(repo, cache):
    if repo not in cache:
        return False
    last_fetch = cache[repo]['last_fetch']
    return datetime.utcnow() - timedelta(hours=24) <= last_fetch

def log(message):
    print(f"{datetime.utcnow().isoformat() + 'Z'} {message}", file=sys.stderr)

def fetch_repo_data(repo):
    url = f"https://api.github.com/repos/{repo}"
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
        if 'full_name' not in data or 'stargazers_count' not in data:
            log(f"Cache miss: Missing required fields in API response for {repo}")
            return None
        return (data['full_name'], data['stargazers_count'])
    except requests.RequestException as e:
        log(f"Fetch failure for {repo}: {str(e)}")
        return None

def main():
    args = parse_args()
    repo = args.repo
    cache = load_cache()

    if is_cache_valid(repo, cache):
        log(f"Cache hit for {repo}")
        last_fetch = cache[repo]['last_fetch']
        full_name, stargazers_count = cache[repo]['data']
        print(f"{full_name} {stargazers_count}")
        return

    log(f"Cache miss for {repo}")
    data = fetch_repo_data(repo)
    if data is None:
        sys.exit(1)

    full_name, stargazers_count = data
    cache[repo] = {
        'last_fetch': datetime.utcnow(),
        'data': data
    }
    save_cache(cache)
    print(f"{full_name} {stargazers_count}")

if __name__ == "__main__":
    main()

import argparse
import json
import os
