def read_cache():
    try:
        with open(get_cache_path(), 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return None

def write_cache(identifier, fetch_time, full_name, stargazers_count):
    cache_entry = {
        'identifier': identifier,
        'fetch_time': fetch_time,
        'full_name': full_name,
        'stargazers_count': stargazers_count
    }
    with open(get_cache_path(), 'w') as f:
        json.dump(cache_entry, f)

def is_cache_valid(cache_entry):
    if not cache_entry:
        return False
    current_time = time.time()
    fetch_time = cache_entry['fetch_time']
    return current_time - fetch_time < 24 * 3600

def fetch_repo_data(identifier):
    url = f'https://api.github.com/repos/{identifier}'
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
        if 'full_name' not in data or 'stargazers_count' not in data:
            raise ValueError("Missing required fields in response")
        return data['full_name'], data['stargazers_count']
    except requests.RequestException as e:
        raise Exception(f"HTTP request failed: {e}")
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid JSON response: {e}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('identifier', help='Repository identifier in format owner/repo')
    args = parser.parse_args()

    cache = read_cache()
    identifier = args.identifier

    if cache and is_cache_valid(cache):
        print(f"{cache['full_name']} {cache['stargazers_count']}")
