        print(f"{full_name} {stargazers_count}")
        write_cache(identifier, time.time(), full_name, stargazers_count)
        sys.stderr.write(f"{datetime.utcnow().isoformat()} Cache miss\n")
    except Exception as e:
        sys.stderr.write(f"{datetime.utcnow().isoformat()} Fetch failure: {str(e)}\n")
        sys.exit(1)

if __name__ == "__main__":
