import argparse
import json
import os
import sys
import time
from datetime import datetime, timedelta

def get_cache_path():
    return os.path.expanduser("~/.repo_cache.dat")

def read_cache():
    try:
        with open(get_cache_path(), "r") as f:
            data = json.load(f)
            return data
    except (FileNotFoundError, json.JSONDecodeError):
        return None

def write_cache(identifier, fetch_time, full_name, stargazers_count):
    data = {
        "identifier": identifier,
        "fetch_time": fetch_time,
        "full_name": full_name,
        "stargazers_count": stargazers_count
    }
    with open(get_cache_path(), "w") as f:
        json.dump(data, f)

def fetch_repo_data(owner, repo):
    url = f"https://api.github.com/repos/{owner}/{repo}"
    try:
        response = json.loads(sys.stdin.read())
    except json.JSONDecodeError:
        sys.stderr.write(f"{datetime.utcnow().isoformat()} fetch failure\n")
        sys.exit(1)

    if "full_name" not in response or "stargazers_count" not in response:
        sys.stderr.write(f"{datetime.utcnow().isoformat()} fetch failure\n")
        sys.exit(1)

    return response["full_name"], response["stargazers_count"]

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("identifier", help="Repository identifier in the form owner/repo")
    args = parser.parse_args()

    cache_data = read_cache()
    identifier = args.identifier
    current_time = datetime.utcnow()

    if cache_data and cache_data["identifier"] == identifier:
        cache_time = datetime.fromisoformat(cache_data["fetch_time"])
        if current_time - cache_time < timedelta(hours=24):
            sys.stdout.write(f"{cache_data['full_name']} {cache_data['stargazers_count']}\n")
            sys.stderr.write(f"{current_time.isoformat()} cache hit\n")
            return

    try:
        full_name, stargazers_count = fetch_repo_data(*identifier.split('/'))
    except Exception as e:
        sys.stderr.write(f"{datetime.utcnow().isoformat()} fetch failure\n")
        sys.exit(1)

    sys.stdout.write(f"{full_name} {stargazers_count}\n")
    write_cache(identifier, current_time.isoformat(), full_name, stargazers_count)
    sys.stderr.write(f"{current_time.isoformat()} cache miss\n")

if __name__ == "__main__":
    main()
